mapper.select:
select * from ( select ecb.id, eid.business_date, ec.org_id as org_id, ec.contract_code as contract_code, ec.contract_name as contract_name, ec.client_code as client_code, ec.client_name as client_name, ec.financial_contract_status as financialContractStatus, coalesce(ecb.receivable_rent_amount,0) as receivableLeaseAmount, coalesce(ecb.receivable_residual_value_amount,0) as receivableLastAmount, coalesce(ecb.receivable_outtax_amount,0) as receivableLastAmountd, coalesce(ecb.receivable_downpayment_amount,0) as receivableFirstAmount, coalesce(ecb.receivable_insurance_amount,0) as receivableInsuranceAmount, coalesce(ecb.receivable_commission_amount,0) as receivableProcedureAmount, coalesce(ecb.receivable_otherincome_amount,0) as receiveOtherRevenues, coalesce(ecb.unrealized_revenue_amount,0) as receiveOtherRevenuesd, coalesce(ecb.receivable_default_interest_amount,0) as recycleDefaultInterestAmount, coalesce(ecb.receivable_terminate_amount,0) as receiveTerminateProcedureAmount, coalesce(ecb.lessee_margin_amount,0)as receivableMarginAmount, coalesce(ecb.lease_revenue_amount,0)+coalesce(ecb.lease_revenue3_amount,0)+coalesce(ecb.lease_revenue6_amount,0) as leaseRevenueAmount, coalesce(ecb.receivable_outtax_amount,0) as receivableOuttaxAmount, coalesce(ecb.depreciation_loss_reverse_amount,0) as depreciationLossAmount, coalesce(ecb.depreciation_reserves_balance,0) +coalesce(ecb.depreciation_loss_reverse_amount,0) as depreciationReservesAmount, coalesce(ecb.depreciation_reserves_balance,0) as depreciationAmount from eg_interface_data eid inner join eg_voucher ev on eid.id = ev.interface_data_id inner join eg_contract_balance ecb on ev.id = ecb.voucher_id inner join eg_contract ec on ecb.contract_code = ec.contract_code and ec.org_id = ecb.org_id where 1 = 1 and eid.org_id is not null and eid.business_date is not null and ev.del_flag ='0' and ecb.del_flag ='0' and ev.sub_scene_type = '25' and eid.del_flag = '0'
and to_char(eid.business_date, 'yyyy-MM') = #{condition.businessDate}
and eid.org_id = #{condition.orgId}
and eid.contract_code like #{condition.contractCode}
and eid.client_name like #{condition.clientName}
and ec.financial_contract_status = #{condition.financialContractStatus}
) s where 1=1
and s.depreciationAmount != 0
and s.depreciationAmount = 0
order by s.contract_code,s.client_code,s.id asc

select eid.id as interfaceId, eid.business_date, null as voucherDate, eid.scene_code, es.scene_name, null as periodCode, eid.client_code, eid.client_name from eg_interface_data eid inner join eg_scene es on eid.scene_code = es.scene_code where 1=1
and eid.contract_code = #{param.contractCode}
and eid.org_id = #{param.orgId}

mapper.sql:
select to_char(to_date(cast(b.period_code as varchar),'YYYYMM'),'yyyy-MM') businessDate, b.org_id, sum(b.depreciationLossAmount) as reversalProvisionAmount, sum(b.leaseRevenueAmount) as revenueFinance from ( select a.*, ( select sum(coalesce(c.receivable_outtax_amount, 0)) from eg_voucher v inner join eg_contract_balance c on v.id = c.voucher_id where 1 = 1 and v.del_flag = '0' and c.del_flag = '0' and v.scene_code = 'KJFP' and v.voucher_status in ('2', '3', '4') and v.valid_flag = '1' and a.contract_code = c.contract_code and a.org_id = c.org_id
and v.period_code >= #{condition.startPeriodCode} and c.period_code >= #{condition.startPeriodCode}
and v.period_code <= #{condition.endPeriodCode} and c.period_code <= #{condition.endPeriodCode}
and c.org_id = #{condition.orgId}
) as receivableLastAmountd, ( select sum(coalesce(eve2.credit_amount, 0)) from eg_voucher ev2 inner join eg_voucher_entry eve2 on ev2.id = eve2.voucher_id where 1 = 1
and ev2.period_code >= #{condition.startPeriodCode} and eve2.period_code >= #{condition.startPeriodCode}
and ev2.period_code <= #{condition.endPeriodCode} and eve2.period_code <= #{condition.endPeriodCode}
and ev2.org_id = #{condition.orgId}
and ev2.contract_code = a.contract_code and ev2.org_id = a.org_id and sub_scene_type in ('25', '核销回款') and eve2.account_code = '2221.01.05' and ev2.del_flag = '0' and eve2.del_flag = '0' and ev2.voucher_status in ('2', '3', '4') and ev2.valid_flag = '1' )as receivableOuttaxAmount, ec.client_code, ec.financial_contract_status, ec.client_name from ( select ecb.period_code, ecb.org_id, ecb.contract_code, sum(coalesce(ecb.receivable_rent_amount, 0)) as receivableLeaseAmount, sum(coalesce(ecb.receivable_residual_value_amount, 0)) as receivableLastAmount, sum(coalesce(ecb.receivable_downpayment_amount, 0)) as receivableFirstAmount, sum(coalesce(ecb.receivable_insurance_amount, 0)) as receivableInsuranceAmount, sum(coalesce(ecb.receivable_commission_amount, 0)) as receivableProcedureAmount, sum(coalesce(ecb.receivable_otherincome_amount, 0)) as receiveOtherRevenues, sum(coalesce(ecb.unrealized_revenue_amount, 0)) as receiveOtherRevenuesd, sum(coalesce(ecb.receivable_default_interest_amount, 0)) as recycleDefaultInterestAmount, sum(coalesce(ecb.receivable_terminate_amount, 0)) as receiveTerminateProcedureAmount, sum(coalesce(ecb.lessee_margin_amount, 0))as receivableMarginAmount, sum(coalesce(ecb.depreciation_loss_reverse_amount, 0))*-1 as depreciationLossAmount, sum(coalesce(ecb.lease_revenue_amount, 0)+ coalesce(ecb.lease_revenue3_amount, 0)+ coalesce(ecb.lease_revenue6_amount, 0)) as leaseRevenueAmount -- coalesce(ecb.depreciation_reserves_balance,0) +coalesce(ecb.depreciation_loss_reverse_amount,0) as -- depreciationReservesAmount, -- coalesce(ecb.depreciation_reserves_balance,0) as depreciationAmount
from eg_voucher ev inner join eg_contract_balance ecb on ev.id = ecb.voucher_id where 1 = 1 and ev.del_flag = '0' and ecb.del_flag = '0' and ev.sub_scene_type in ('25', '核销回款') and ev.voucher_status in ('2', '3', '4') and ev.valid_flag = '1'
and ev.period_code >= #{condition.startPeriodCode} and ecb.period_code >= #{condition.startPeriodCode}
and ev.period_code <= #{condition.endPeriodCode} and ecb.period_code <= #{condition.endPeriodCode}
and ecb.org_id = #{condition.orgId}
group by ecb.period_code, ecb.org_id, ecb.contract_code ) a inner join eg_contract ec on a.contract_code = ec.contract_code and a.org_id = ec.org_id and ec.del_flag = '0' ) b group by b.period_code, b.org_id

select k.*, to_char(to_date(cast(k.period_code as varchar),'YYYYMM'),'yyyy-MM') businessDate, (coalesce(k.depreciationReservesAmount,0)-coalesce(k.depreciationLossAmount,0)) as depreciationAmount from ( select a.*, ( select sum(coalesce(eve2.debit_amount, 0)) from eg_voucher ev2 inner join eg_voucher_entry eve2 on ev2.id = eve2.voucher_id where 1 = 1
and ev2.period_code = #{condition.periodCode} and eve2.period_code = #{condition.periodCode}
and ev2.org_id = #{condition.orgId}
and ev2.contract_code = a.contract_code and ev2.org_id = a.org_id and sub_scene_type = '25' and eve2.account_code = '1531.01.09' and ev2.del_flag = '0' and eve2.del_flag = '0' and ev2.voucher_status in ('2', '3', '4') and ev2.valid_flag = '1' ) as receivableLastAmountd, ( select sum(coalesce(eve2.credit_amount, 0)) from eg_voucher ev2 inner join eg_voucher_entry eve2 on ev2.id = eve2.voucher_id where 1 = 1
and ev2.period_code = #{condition.periodCode} and eve2.period_code = #{condition.periodCode}
and ev2.org_id = #{condition.orgId}
and ev2.contract_code = a.contract_code and ev2.org_id = a.org_id and sub_scene_type = '25' and eve2.account_code = '2221.01.05' and ev2.del_flag = '0' and eve2.del_flag = '0' and ev2.voucher_status in ('2', '3', '4') and ev2.valid_flag = '1' )as receivableOuttaxAmount, ( select max(r.bad_debt_write_off_balance) from eg_charge_off_summary_report r where 1=1
and r.period_code = #{condition.lastPeriodCode}
and r.org_id = #{condition.orgId}
and r.contract_code = a.contract_code and r.org_id = a.org_id and r.del_flag ='0' ) as depreciationReservesAmount, ec.client_code, ec.financial_contract_status, ec.client_name from ( select ecb.period_code, ecb.org_id, ecb.contract_code, sum(coalesce(ecb.receivable_rent_amount, 0)) as receivableLeaseAmount, sum(coalesce(ecb.receivable_residual_value_amount, 0)) as receivableLastAmount, sum(coalesce(ecb.receivable_downpayment_amount, 0)) as receivableFirstAmount, sum(coalesce(ecb.receivable_insurance_amount, 0)) as receivableInsuranceAmount, sum(coalesce(ecb.receivable_commission_amount, 0)) as receivableProcedureAmount, sum(coalesce(ecb.receivable_otherincome_amount, 0)) as receiveOtherRevenues, sum(coalesce(ecb.unrealized_revenue_amount, 0)) as receiveOtherRevenuesd, sum(coalesce(ecb.receivable_default_interest_amount, 0)) as recycleDefaultInterestAmount, sum(coalesce(ecb.receivable_terminate_amount, 0)) as receiveTerminateProcedureAmount, sum(coalesce(ecb.lessee_margin_amount, 0))as receivableMarginAmount, sum(coalesce(ecb.depreciation_loss_reverse_amount, 0))*-1 as depreciationLossAmount, sum(coalesce(ecb.lease_revenue_amount, 0)+ coalesce(ecb.lease_revenue3_amount, 0)+ coalesce(ecb.lease_revenue6_amount, 0)) as leaseRevenueAmount from eg_voucher ev inner join eg_contract_balance ecb on ev.id = ecb.voucher_id where 1 = 1 and ev.del_flag = '0' and ecb.del_flag = '0' and ev.sub_scene_type = '25' and ev.voucher_status in ('2', '3', '4') and ev.valid_flag = '1'
and ev.period_code = #{condition.periodCode} and ecb.period_code = #{condition.periodCode}
and ecb.org_id = #{condition.orgId}
group by ecb.period_code, ecb.org_id, ecb.contract_code ) a inner join eg_contract ec on a.contract_code = ec.contract_code and a.org_id = ec.org_id and ec.del_flag = '0'
and ec.client_name like #{condition.clientName}
and ec.financial_contract_status = #{condition.financialContractStatus}
and ec.contract_code like #{condition.contractCode}
and ec.client_code like #{condition.clientCode}
) k where 1=1
and k.depreciationAmount != 0
and k.depreciationAmount = 0
order by k.contract_code,k.client_code asc
